```

```ts
// src/main/lib/convert.ts
export async function parquetToJson(filePath: string, outputPath?: string): Promise<ParquetToTxtResult> {
  try {
    const rows = await readParquetRows(filePath)
    const out = outputPath ?? join(dirname(filePath), `${basename(filePath, extname(filePath))}.json`)
    await writeFile(out, JSON.stringify(rows, null, 2), 'utf8')
    return { ok: true, outputPath: out, rowCount: rows.length }
  } catch (error) {
    return { ok: false, error: error instanceof Error ? error.message : String(error) }
  }
}
