  const seriesColorIndex = new Map<string, number>();
  let nextSeriesIndex = 0;
  const getSeriesColor = (group: string | undefined, pointIndex: number) => {
    if (!group) return colors[pointIndex % colors.length];
    if (!seriesColorIndex.has(group)) seriesColorIndex.set(group, nextSeriesIndex++);
    return colors[seriesColorIndex.get(group)! % colors.length];
  };
  // ... map rows to { x, y, group, color }
}
