type ScatterPoint = ChartDataPoint & { y: number; coordLabel: string };

function groupBySeries(data: ScatterPoint[]): [string, ScatterPoint[]][] {
  const map = new Map<string, ScatterPoint[]>();
  for (const point of data) {
    const key = point.group || "Other";
    const series = map.get(key) ?? [];
    series.push(point);
    map.set(key, series);
  }
  return [...map.entries()];
}
