## 3. Data Binding (`src/lib/charts/`)

### bindData.ts
```ts
// lines 3-51
export interface ChartDataPoint {
  label: string;
  value: number;
  group?: string;
  color?: string;
}

export function getChartData(doc: MapperDocument, chart: ChartConfig): ChartDataPoint[] {
  let rows: SheetRow[] = [];
  if (chart.inlineData.length > 0) {
    rows = chart.inlineData;
  } else if (chart.sheetId && chart.range) {
    const sheet = doc.sheets.find((s) => s.id === chart.sheetId);
    if (sheet) rows = sheet.rows.slice(chart.range.startRow, chart.range.endRow + 1);
  } else {
    const sheet = doc.sheets[0];
    if (sheet) rows = sheet.rows;
  }

  const binding = doc.bindings.find(
    (b) => b.targetType === "chart" && b.targetId === chart.id
  );
  if (binding && chart.inlineData.length === 0) {
    const sheet = doc.sheets.find((s) => s.id === binding.sourceSheetId);
    if (sheet) rows = sheet.rows.slice(binding.range.startRow, binding.range.endRow + 1);
  }

  const data = rows
    .filter((r) => r.label.trim() !== "" || r.value.trim() !== "")
    .map((r, i) => ({
      label: r.label || "—",
      value: parseFloat(r.value) || 0,
      group: r.group || undefined,
      color: chart.style.colors[i % chart.style.colors.length],
    }));

  if (chart.style.sortOrder === "asc") return [...data].sort((a, b) => a.value - b.value);
  if (chart.style.sortOrder === "desc") return [...data].sort((a, b) => b.value - a.value);
  return data;
}
```

Priority: (1) `inlineData` (wins when non-empty), (2) `chart.sheetId` + `chart.range`, (3) first sheet fallback, (4) `DataBinding` only when `inlineData` is empty. Values parsed with `parseFloat`; non-numeric → 0. Sorting applied after mapping.

### chartColumns.ts
```ts
