export function defaultChartColumns(): SheetRow[] {
  return [
    { id: crypto.randomUUID(), label: "Series A", value: "40", group: "" },
    { id: crypto.randomUUID(), label: "Series B", value: "65", group: "" },
    { id: crypto.randomUUID(), label: "Series C", value: "25", group: "" },
  ];
}

export function columnsFromSheetRows(rows: SheetRow[]): SheetRow[] {
  return rows.map((r) => ({
    id: crypto.randomUUID(),
    label: r.label,
    value: r.value,
    group: r.group,
  }));
}

export function defaultColumnColors(count: number): string[] {
  return Array.from({ length: count }, (_, i) => DEFAULT_COLORS[i % DEFAULT_COLORS.length]);
}
```

## 4. State Management (`src/store/documentStore.ts`)

Chart CRUD actions:
- `addChart(type, sheetId?, range?)` — creates chart, seeds `inlineData`, adds library item, switches to charts view.
- `updateChart(id, updates)` — partial update; renames library item if title changes.
- `addChartColumn(chartId)` — adds a new `SheetRow` column + color.
- `updateChartColumn(chartId, columnId, {label?, value?, color?})` — edits column fields or per-column color.
- `removeChartColumn(chartId, columnId)` — removes column (min 1 required).
- `removeChart(id)` — deletes chart, bindings, library item.
- `selectChart(id)` — sets `selectedChartId`, commits text drafts.

`addChart` creation flow (lines 392-439):
```ts
addChart: (type, sheetId, range) => {
  const state = get();
  const sheet = state.document.sheets.find((sh) => sh.id === sheetId) ?? state.document.sheets[0];
  const chartId = crypto.randomUUID();
  const titles: Record<ChartType, string> = {
    "bar-v": "Vertical Bar Chart",
    "bar-h": "Horizontal Bar Chart",
    pie: "Pie Chart",
  };
  const title = titles[type];

  let inlineData = defaultChartColumns();
  if (sheetId && range && sheet) {
    const rows = sheet.rows.slice(range.startRow, range.endRow + 1);
    if (rows.length > 0) inlineData = columnsFromSheetRows(rows);
  }

  const chart: ChartConfig = {
    id: chartId,
    type,
    title,
    sheetId: null,
    range: null,
    inlineData,
    style: {
      title,
      showLabels: true,
      colors: defaultColumnColors(inlineData.length),
      sortOrder: "none",
    },
    position: { x: 0, y: 0 },
  };
  // ... pushes to document.charts, adds library item, sets activeView: "charts"
};
```

